        def ns(a):
            p=a.group(1)
            return a.group(0) if p in keep else ''
        t=re.sub(r'\s+xmlns:([\w-]+)=("[^"]*"|\'[^\']*\')', ns, t)
        t=re.sub(r'\s*=\s*', '=', t)
